action_details.action_postfix:
// Physical nexus established - filing required
true result.mo_has_nexus xdef
"Missouri filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.mo_has_nexus xdef
"Missouri filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Missouri state additions
0.0 /mo_additions xdef

// Common Missouri additions:
// - Federal bond interest
// - IRC 199A qualified business income deduction addback
// - State income taxes deducted on federal return

result.mo_us_interest_income 0.0 ne
{
  mo_additions result.mo_us_interest_income add /mo_additions xdef
} if

mo_additions result.mo_state_additions xdef

// Calculate Missouri state subtractions
0.0 /mo_subtractions xdef

// UNIQUE MISSOURI FEATURE: 50% federal income tax deduction
// Missouri allows deduction of 50% of federal income tax paid
result.federal_tax_liability result.mo_federal_tax_deduction_percentage mul
/mo_federal_tax_deduction xdef
mo_subtractions mo_federal_tax_deduction add /mo_subtractions xdef

// Common Missouri subtractions:
// - Missouri municipal bond interest
// - Missouri NOL deduction

result.mo_municipal_interest 0.0 ne
{
  mo_subtractions result.mo_municipal_interest add /mo_subtractions xdef
} if

mo_subtractions result.mo_state_subtractions xdef

"Missouri additions: $" result.mo_state_additions cvs strconcat ", subtractions: $" strconcat result.mo_state_subtractions cvs strconcat job.audit_trail swap addto
"Missouri 50% federal tax deduction: $" mo_federal_tax_deduction cvs strconcat job.audit_trail swap addto

// Calculate Missouri taxable income
// Federal taxable income apportioned to MO + additions - subtractions
// Note: Subtractions include 50% federal tax deduction
result.mo_apportioned_income
result.mo_state_additions add
result.mo_state_subtractions sub
0.0 max
result.mo_taxable_income xdef

// Calculate Missouri tax using flat rate: 4.0%
result.mo_taxable_income result.mo_corp_tax_rate mul
/mo_tax_before_credits xdef

// Subtract Missouri state credits (jobs creation, historic preservation, film production, etc.)
mo_tax_before_credits result.mo_state_credits sub 0.0 max
result.mo_tax_liability xdef

// Calculate refund or amount owed
result.mo_estimated_payments result.mo_tax_liability sub
result.mo_refund_or_owed xdef

"Missouri taxable income: $" result.mo_taxable_income cvs strconcat job.audit_trail swap addto
"Missouri tax liability (4.0%, effective ~3.6% after 50% federal tax deduction): $" result.mo_tax_liability cvs strconcat job.audit_trail swap addto

// No taxable income - no tax liability
// 50% federal tax deduction may create zero/negative MO income
0.0 result.mo_taxable_income xdef
0.0 result.mo_tax_liability xdef
result.mo_estimated_payments result.mo_refund_or_owed xdef
"Missouri tax liability: $0 (no taxable income)" job.audit_trail swap addto
